import json

def generate_json(score, response):
    return {
      "score": score,
      "response": response
    }

def get_user_response():
    user_response = input("Please answer the question: 1 to 5:\n")
    return int(user_response)


def main():
    score = None
    response = ''

    print('Here is a characteristic that may or may not apply to you:\n')

    score = get_user_response()

    print('What is your response?\n')
    response = input()

    json_output = generate_json(score, response)
    print

